files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --highlight: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', monospace;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--highlight);
  border-radius: 0;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 var(--highlight);
}

.pixel-text {
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: bold;
}

h1 {
  font-size: 24px;
  margin-bottom: 24px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--highlight);
}

.question {
  font-size: 28px;
  margin-bottom: 24px;
  min-height: 40px;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 20px;
  font-weight: bold;
  cursor: pointer;
  border: 3px solid var(--highlight);
  background: var(--bg);
  color: var(--text);
  padding: 12px 24px;
  min-width: 100px;
  transition: background 0.1s, transform 0.1s;
  text-transform: uppercase;
  letter-spacing: 1px;
}

button:hover:not(:disabled) {
  background: var(--highlight);
  transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0 var(--accent);
}

button:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: none;
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.answer-btn {
  background: var(--highlight);
  min-width: 120px;
}

.answer-btn:hover:not(:disabled) {
  background: var(--accent);
}

.score-line {
  font-size: 20px;
  margin-bottom: 24px;
}

#score {
  color: var(--accent);
  font-weight: bold;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.ctrl-btn {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
}

.ctrl-btn:hover:not(:disabled) {
  background: var(--text);
  border-color: var(--text);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .question {
    font-size: 24px;
  }
  button {
    font-size: 18px;
    padding: 10px 16px;
    min-width: 80px;
  }
}

(function() {
  'use strict';

  const questionEl = document.getElementById('question');
  const answerA = document.getElementById('answer-a');
  const answerB = document.getElementById('answer-b');
  const scoreEl = document.getElementById('score');
  const nextBtn = document.getElementById('next');
  const restartBtn = document.getElementById('restart');

  let currentQuestion = 1;
  let score = 0;
  let answered = false;

  const questions = {
    1: { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
    2: { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
  };

  function renderQuestion() {
    const q = questions[currentQuestion];
    questionEl.textContent = q.text;
    answerA.textContent = q.a;
    answerB.textContent = q.b;
    answerA.disabled = false;
    answerB.disabled = false;
    answered = false;
  }

  function handleAnswer(choice) {
    if (answered) return;
    answered = true;
    answerA.disabled = true;
    answerB.disabled = true;
    if (questions[currentQuestion].correct === choice) {
      score += 1;
      scoreEl.textContent = score;
    }
  }

  function handleNext() {
    if (currentQuestion === 1) {
      currentQuestion = 2;
      renderQuestion();
    } else if (currentQuestion === 2) {
      currentQuestion = 3;
      questionEl.textContent = 'Finished';
      answerA.disabled = true;
      answerB.disabled = true;
    }
  }

  function handleRestart() {
    currentQuestion = 1;
    score = 0;
    scoreEl.textContent = '0';
    renderQuestion();
  }

  answerA.addEventListener('click', function() { handleAnswer('a'); });
  answerB.addEventListener('click', function() { handleAnswer('b'); });
  nextBtn.addEventListener('click', handleNext);
  restartBtn.addEventListener('click', handleRestart);

  renderQuestion();
})();
